def gpx_fields_from_xml(class_or_instance: Any, node: Any, version: str) -> Any:
    if isinstance(class_or_instance, type):
        instance = class_or_instance()
    else:
        instance = class_or_instance

    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    for gpx_field in fields:
        if isinstance(gpx_field, str):
            continue

        value = gpx_field.from_xml(node, version)
        setattr(instance, gpx_field.name, value)

    return instance

def from_xml(self, node: Any, version: str) -> Any:
    return gpx_fields_from_xml(self, node, version)
